user www-data;
worker_processes auto;
worker_rlimit_nofile 65535;
pid /run/nginx.pid;
error_log /var/log/nginx/error.log crit;
include /etc/nginx/modules-enabled/*.conf;

events {
    worker_connections 16384;
    multi_accept on;
    use epoll;
}

http {
    sendfile on;
    tcp_nopush on;
    tcp_nodelay on;
    types_hash_max_size 2048;
    server_tokens off;

    include /etc/nginx/mime.types;
    default_type application/octet-stream;

    keepalive_timeout 65;
    keepalive_requests 1000;
    client_body_timeout 10;
    client_header_timeout 10;
    send_timeout 10;
    reset_timedout_connection on;

    proxy_buffer_size 32k;
    proxy_buffers 16 32k;
    proxy_busy_buffers_size 64k;
    proxy_connect_timeout 5;
    proxy_read_timeout 30;
    proxy_send_timeout 10;

    access_log off;

    gzip on;
    gzip_vary on;
    gzip_proxied any;
    gzip_comp_level 4;
    gzip_types text/plain text/css application/json application/javascript text/xml application/xml application/xml+rss text/javascript;

    map $http_upgrade $connection_upgrade { default upgrade; "" close; }

    proxy_cache_path /var/cache/nginx/juice_shop levels=1:2 keys_zone=juice_cache:10m max_size=100m inactive=5m use_temp_path=off;
    map $http_x_forwarded_for $juice_affinity {
        default $http_x_forwarded_for;
        "" $remote_addr;
    }
    upstream juice_shop {
        server 127.0.0.1:3001 max_fails=3 fail_timeout=10s;
        server 127.0.0.1:3002 max_fails=3 fail_timeout=10s;
        server 127.0.0.1:3003 max_fails=3 fail_timeout=10s;
        server 127.0.0.1:3004 max_fails=3 fail_timeout=10s;
        hash $juice_affinity consistent;
        keepalive 64;
    }

    upstream dvwa {
        server 127.0.0.1:8101 max_fails=3 fail_timeout=10s;
        server 127.0.0.1:8102 max_fails=3 fail_timeout=10s;
        server 127.0.0.1:8103 max_fails=3 fail_timeout=10s;
        server 127.0.0.1:8104 max_fails=3 fail_timeout=10s;
        hash $cookie_PHPSESSID consistent;
        keepalive 128;
    }

    upstream vampi {
        server 127.0.0.1:5101 max_fails=3 fail_timeout=10s;
        server 127.0.0.1:5102 max_fails=3 fail_timeout=10s;
        server 127.0.0.1:5103 max_fails=3 fail_timeout=10s;
        server 127.0.0.1:5104 max_fails=3 fail_timeout=10s;
        ip_hash;
        keepalive 128;
    }

    upstream httpbin_up {
        server 127.0.0.1:8201 max_fails=3 fail_timeout=10s;
        server 127.0.0.1:8202 max_fails=3 fail_timeout=10s;
        server 127.0.0.1:8203 max_fails=3 fail_timeout=10s;
        server 127.0.0.1:8204 max_fails=3 fail_timeout=10s;
        keepalive 128;
    }

    upstream whoami_up {
        server 127.0.0.1:8082 max_fails=3 fail_timeout=10s;
        server 127.0.0.1:8083 max_fails=3 fail_timeout=10s;
        server 127.0.0.1:8084 max_fails=3 fail_timeout=10s;
        server 127.0.0.1:8085 max_fails=3 fail_timeout=10s;
        keepalive 128;
    }
    upstream csd_demo {
        server 127.0.0.1:5001 max_fails=3 fail_timeout=10s;
        server 127.0.0.1:5002 max_fails=3 fail_timeout=10s;
        server 127.0.0.1:5003 max_fails=3 fail_timeout=10s;
        server 127.0.0.1:5004 max_fails=3 fail_timeout=10s;
        ip_hash;
        keepalive 128;
    }

    map $cookie_dvga_replica $dvga_affinity {
        default $cookie_dvga_replica;
        "" $request_id;
    }
    upstream dvga_graphql {
        server 127.0.0.1:5201 max_fails=3 fail_timeout=10s;
        server 127.0.0.1:5202 max_fails=3 fail_timeout=10s;
        server 127.0.0.1:5203 max_fails=3 fail_timeout=10s;
        server 127.0.0.1:5204 max_fails=3 fail_timeout=10s;
        hash $dvga_affinity consistent;
        keepalive 128;
    }

    upstream restaurant {
        server 127.0.0.1:8301 max_fails=3 fail_timeout=10s;
        server 127.0.0.1:8302 max_fails=3 fail_timeout=10s;
        server 127.0.0.1:8303 max_fails=3 fail_timeout=10s;
        server 127.0.0.1:8304 max_fails=3 fail_timeout=10s;
        keepalive 128;
    }

    include /etc/nginx/conf.d/*.conf;
    include /etc/nginx/sites-enabled/*;
}

// Generated directory listings may be changed after their original length is set.
// Let Node frame the final body rather than transmitting a stale Content-Length.
const http = require('node:http');
const original = http.ServerResponse.prototype.setHeader;
http.ServerResponse.prototype.setHeader = function(name, value) {
  if (name.toLowerCase() === 'content-length' && new Error().stack.includes('serve-index')) {
    this.removeHeader('Content-Length');
    return this;
  }
  return original.call(this, name, value);
};

const fs = require('node:fs');
const path = require('node:path');
function patchBundles(directory) {
  if (!fs.existsSync(directory)) return;
  for (const entry of fs.readdirSync(directory, {withFileTypes:true})) {
    const file = path.join(directory, entry.name);
    if (entry.isDirectory()) patchBundles(file);
    else if (entry.name.endsWith('.js')) {
      const original = fs.readFileSync(file, 'utf8');
      const patched = original.replaceAll('"/assets/i18n/"', '"/juice-shop/assets/i18n/"').replaceAll("'/assets/i18n/'", "'/juice-shop/assets/i18n/'").replaceAll('`/assets/i18n/`', '`/juice-shop/assets/i18n/`').replaceAll('JuiceShop_Logo.png', 'JuiceShopCTF_Logo.png');
      if (patched !== original) fs.writeFileSync(file, patched);
    }
  }
}
patchBundles('/juice-shop/frontend/dist');

// Reapply the source adapter before each bundle read: customization may regenerate files.
const originalReadFile = fs.readFile;
fs.readFile = function(file, ...args) {
  if (typeof file === 'string' && file.endsWith('.js') && file.startsWith('/juice-shop/frontend/')) {
    const original = fs.readFileSync(file, 'utf8');
    const patched = original.replaceAll('`/assets/i18n/`', '`/juice-shop/assets/i18n/`').replaceAll('JuiceShop_Logo.png', 'JuiceShopCTF_Logo.png');
    if (patched !== original) fs.writeFileSync(file, patched);
  }
  return originalReadFile.call(this, file, ...args);
};

// The frontend base remains published on direct replicas; strip it before native dispatch.
const originalEmit = http.Server.prototype.emit;
http.Server.prototype.emit = function(event, request, ...args) {
  if ((event === 'request' || event === 'upgrade') && request.url.startsWith('/juice-shop/')) {
    request.url = request.url.slice('/juice-shop'.length);
  }
  return originalEmit.call(this, event, request, ...args);
};

// Keep the licensed display font on the published application route.
const fontDirectory = '/juice-shop/frontend/dist/frontend/assets/public/fonts';
fs.mkdirSync(fontDirectory, {recursive:true});
fs.writeFileSync(path.join(fontDirectory, 'VT323-Regular.ttf'), Buffer.from('__VT323_FONT_BASE64__', 'base64'));
function localFonts(file) {
  if (Buffer.isBuffer(file)) file = file.toString();
  if (typeof file !== 'string' || !file.startsWith('/juice-shop/frontend/') || !file.endsWith('.html')) return;
  const source = fs.readFileSync(file, 'utf8');
  if (source.includes('data-origin-local-font')) return;
  const patched = source.replace(/<link[^>]*href=["']https:\/\/fonts\.(?:googleapis|gstatic)\.com[^>]*>/g, '')
    .replace('</head>', '<style data-origin-local-font>@font-face{font-family:VT323;src:url(assets/public/fonts/VT323-Regular.ttf) format(\"truetype\");font-display:swap}</style></head>');
  if (patched !== source) fs.writeFileSync(file, patched);
}
const bundleReadFile = fs.readFile;
fs.readFile = function(file, ...args) {
  localFonts(file);
  return bundleReadFile.call(this, file, ...args);
};

function patchHtml(directory) {
  for (const entry of fs.readdirSync(directory, {withFileTypes:true})) {
    const file = path.join(directory, entry.name);
    if (entry.isDirectory()) patchHtml(file);
    else if (entry.name.endsWith('.html')) localFonts(file);
  }
}
patchHtml('/juice-shop/frontend/dist');

