from datetime import datetime, timezone

from flask import Flask, Response, jsonify, render_template, request, url_for

app = Flask(__name__)

import sqlite3
from werkzeug.middleware.proxy_fix import ProxyFix

app.wsgi_app = ProxyFix(app.wsgi_app, x_prefix=1)

def database():
    connection = sqlite3.connect('/state/exfil.sqlite', timeout=10)
    connection.execute('CREATE TABLE IF NOT EXISTS entries (id INTEGER PRIMARY KEY, data TEXT NOT NULL)')
    return connection

def entries():
    import json
    with database() as connection:
        return [json.loads(row[0]) for row in connection.execute('SELECT data FROM entries ORDER BY id')]



@app.route("/")
def checkout():
    return render_template("checkout.html")


@app.route("/checkout.js")
def checkout_js():
    # Served as an EXTERNAL script (its own URL) so F5 XC Client-Side Defense inventories it
    # at page load and — because it reads sensitive payment fields — flags it High Risk. An
    # inline <script> is NOT inventoried, which is why CSD produced zero script statistics
    # while the attack logic lived inline in checkout.html.
    return Response(render_template("checkout.js"), mimetype="application/javascript")


@app.route("/dashboard")
def dashboard():
    return render_template("dashboard.html", entries=entries())


@app.route("/exfil", methods=["POST", "GET"])
def exfil():
    fixture_id = request.headers.get("X-Demo-Fixture", "")
    entry = {
        "fixture_id": fixture_id,
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "source_ip": request.remote_addr,
        "user_agent": request.headers.get("User-Agent", ""),
        "attack_type": request.args.get("type", "unknown"),
    }
    if request.is_json:
        entry["payload"] = request.get_json(silent=True)
    elif request.args.get("d"):
        entry["payload"] = request.args.get("d")
    else:
        entry["payload"] = request.get_data(as_text=True)
    import json
    with database() as connection:
        connection.execute('INSERT INTO entries(data) VALUES (?)', (json.dumps(entry),))
    return jsonify({"status": "received"})


@app.route("/exfil/log")
def exfil_log():
    return jsonify(entries())


@app.route("/exfil/clear", methods=["POST"])
def exfil_clear():
    with database() as connection:
        fixture_id = request.headers.get("X-Demo-Fixture", "")
        if fixture_id:
            import json
            ids = [row[0] for row in connection.execute('SELECT id, data FROM entries') if json.loads(row[1]).get('fixture_id') == fixture_id]
            connection.executemany('DELETE FROM entries WHERE id = ?', [(id,) for id in ids])
        else:
            connection.execute('DELETE FROM entries')
    return jsonify({"status": "cleared"})


@app.route("/health")
def health():
