#!/usr/bin/env python3
"""Guest functional readiness, not /health liveness or WAAP security proof."""
import argparse
import http.cookiejar as cookiejar
from html.parser import HTMLParser
import json
import re
import subprocess
import time
import urllib.parse
import urllib.request
import urllib.error

FAMILIES = {"juice-shop": 3001, "dvwa": 8101, "vampi": 5101,
            "httpbin": 8201, "whoami": 8082, "csd-demo": 5001,
            "dvga": 5201, "restaurant": 8301}
CRAPI = ["crapi-postgres", "crapi-mongo", "crapi-mailhog",
         "crapi-identity", "crapi-community", "crapi-workshop", "crapi-chatbot", "crapi-web"]
DEADLINE = float("inf")

def budget():
    remaining = DEADLINE - time.monotonic()
    if remaining <= 0:
        raise TimeoutError("readiness deadline exceeded")
    return min(5, remaining)

def command(*args):
    return subprocess.run(args, check=True, capture_output=True, text=True,
                          timeout=budget()).stdout.strip()

def http(port, path, data=None, token=None, opener=None, fixture=None):
    headers = {"Content-Type": "application/json"}
    if fixture:
        headers["X-Demo-Fixture"] = fixture
    if token:
        headers["Authorization"] = "Bearer " + token
    request = urllib.request.Request("http://127.0.0.1:" + str(port) + path,
                                     data=data, headers=headers)
    with (opener or urllib.request.build_opener()).open(request, timeout=budget()) as response:
        if response.status != 200:
            raise ValueError("unexpected application response")
        body = response.read(1024 * 1024 + 1)
        if len(body) > 1024 * 1024:
            raise ValueError("oversized response")
        return body.decode("utf-8")

def require(value, message):
    if not value:
        raise ValueError(message)

def container(name, health=False):
    state = json.loads(command("docker", "inspect", "--format", "{{json .State}}", name))
    require(state.get("Running") and not state.get("Restarting"), "container not running")
    if health:
        require(state.get("Health", {}).get("Status") == "healthy", "container not healthy")

class PhaseError(ValueError):
    def __init__(self, phase, cause):
        super().__init__(phase)
        self.phase = phase
        self.error = type(cause).__name__
        self.status = cause.code if isinstance(cause, urllib.error.HTTPError) else None

def diagnostic(exc):
    result = {"error": getattr(exc, "error", type(exc).__name__)}
    if isinstance(exc, PhaseError):
        result["phase"] = exc.phase
    status = getattr(exc, "status", None)
    if isinstance(exc, urllib.error.HTTPError):
        status = exc.code
    if status is not None:
        result["http_status"] = status
    return result

def phase_call(phase, fn, wait=False, container_wait=False):
    # Retry only pre-mutation readiness. Reset endpoints are NEVER blindly retried.
    delay = 0.25
    while True:
        try:
            budget()
            return fn()
        except Exception as exc:
            transient = (isinstance(exc, urllib.error.HTTPError) and exc.code in (429, 503))
            transient = transient or (isinstance(exc, (urllib.error.URLError, OSError))
                                       and not isinstance(exc, urllib.error.HTTPError))
            transient = transient or (container_wait and isinstance(
                exc, (ValueError, subprocess.CalledProcessError)))
            remaining = DEADLINE - time.monotonic()
            if not wait or not transient or remaining <= 0:
                raise PhaseError(phase, exc) from None
            time.sleep(min(delay, remaining))
            delay = min(2, delay * 2)

def dvwa_seeded():
    exists = command("docker", "exec", "dvwa-db", "mariadb", "-udvwa", "-pp@ssw0rd",
                     "-Nse", "SELECT COUNT(*) FROM information_schema.tables WHERE table_schema='dvwa' AND table_name='users'")
    return int(exists) == 1 and int(command(
        "docker", "exec", "dvwa-db", "mariadb", "-udvwa", "-pp@ssw0rd",
        "dvwa", "-Nse", "SELECT COUNT(*) FROM users")) >= 5


class DVWASetup(HTMLParser):
    def __init__(self):
        super().__init__()
        self.form = None
        self.fields = None

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag == "form":
            self.form = {} if attrs.get("method", "").lower() == "post" and attrs.get("action", "#") in ("#", "", "setup.php") else None
        elif tag == "input" and self.form is not None:
            self.form[attrs.get("name")] = attrs.get("value", "")

    def handle_endtag(self, tag):
        if tag == "form":
            if self.form is not None and "create_db" in self.form:
                self.fields = self.form
            self.form = None

def initialize():
    phase_call("dvwa-db:running", lambda: container("dvwa-db"), wait=True, container_wait=True)
    phase_call("dvwa-db:sql-connect", lambda: require(command(
        "docker", "exec", "dvwa-db", "mariadb", "-udvwa", "-pp@ssw0rd",
        "-Nse", "SELECT 1") == "1", "database unreachable"), wait=True, container_wait=True)
    def setup_get(port):
        # Every retry has its own session; its token and POST share the same CookieJar.
        opener = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(cookiejar.CookieJar()))
        page = http(port, "/setup.php", opener=opener)
        setup = DVWASetup()
        setup.feed(page)
        require(setup.fields is not None, "missing DVWA setup form")
        token = setup.fields.get("user_token", "")
        require(re.fullmatch(r"[a-f0-9]+", token), "missing DVWA setup token")
        return opener, token
    for index in range(1, 5):
        phase_call("dvwa-" + str(index) + ":running",
                   lambda i=index: container("dvwa-" + str(i)), wait=True, container_wait=True)
        session = phase_call("dvwa-" + str(index) + ":setup-get",
                             lambda i=index: setup_get(8100+i), wait=True)
        if index == 1:
            opener, token = session
    # login.php invokes dvwaDatabaseConnect: use setup.php BEFORE seeding, login AFTER.
    if not phase_call("dvwa-db:seed-check", dvwa_seeded):
        def setup_post():
            data = urllib.parse.urlencode({"create_db": "Create / Reset Database", "user_token": token}).encode()
            request = urllib.request.Request("http://127.0.0.1:8101/setup.php", data=data,
                                             headers={"Content-Type": "application/x-www-form-urlencoded"})
            with opener.open(request, timeout=budget()) as response:
                require(response.status == 200, "DVWA initialization failed")
                body = response.read(1024 * 1024 + 1)
                require(len(body) <= 1024 * 1024, "oversized response")
                require("<em>Setup successful</em>!" in body.decode("utf-8"), "DVWA setup unsuccessful")
        phase_call("dvwa-1:setup-post", setup_post)
        phase_call("dvwa-db:seed-verify", lambda: require(dvwa_seeded(), "DVWA users missing"))
    for index in range(1, 5):
        phase_call("dvwa-" + str(index) + ":login-get",
                   lambda i=index: replica("dvwa", 8100+i), wait=True)
    # Pinned api_views/main.py populate_db drops/recreates DB and returns 200.
    # / is a pre-seed functional application control; /users/v1 verifies seeding.
    for index, port in enumerate(range(5101, 5105), 1):
        phase = "vampi-" + str(index)
        phase_call(phase + ":running", lambda i=index: container("vampi-" + str(i)),
                   wait=True, container_wait=True)
        phase_call(phase + ":root-get", lambda p=port: require(
            json.loads(http(p, "/")).get("message") == "VAmPI the Vulnerable API",
            "VAmPI application unavailable"), wait=True)
        # Do not interpret any 400/500 as 'already initialized'. Initialize exactly once.
        try:
            replica("vampi", port)
        except urllib.error.HTTPError as error:
            if error.code != 500:
                raise
            phase_call(phase + ":createdb-get", lambda p=port: require(
                json.loads(http(p, "/createdb")).get("message") == "Database populated.",
                "VAmPI initialization unsuccessful"))
        phase_call(phase + ":users-get", lambda p=port: replica("vampi", p), wait=True)

def replica(family, port):
    if family == "juice-shop":
        body = json.loads(http(port, "/rest/products/search?q=apple"))
        require(body.get("status") == "success" and body.get("data"), "product query failed")
    elif family == "dvwa":
        page = http(port, "/login.php")
        require("user_token" in page and "Login" in page, "DVWA login unavailable")
    elif family == "vampi":
        require(json.loads(http(port, "/users/v1")).get("users"), "VAmPI users unavailable")
    elif family == "httpbin":
        require(json.loads(http(port, "/anything/origin-readiness")).get("method") == "GET", "echo mismatch")
        payload = json.dumps({"demo_id": "origin-readiness"}).encode()
        require(json.loads(http(port, "/post", payload)).get("json", {}).get("demo_id") == "origin-readiness", "POST echo mismatch")
    elif family == "whoami":
        require("Hostname:" in http(port, "/") and "GET /" in http(port, "/"), "whoami echo mismatch")
    elif family == "csd-demo":
        require("checkout.js" in http(port, "/"), "checkout missing")
        require("function" in http(port, "/checkout.js"), "checkout script missing")
        import uuid
        fixture = "readiness-" + uuid.uuid4().hex
        try:
            require(json.loads(http(port, "/exfil", b'{"demo_id":"synthetic-readiness"}', fixture=fixture)).get("status") == "received", "synthetic receiver failed")
        finally:
            require(json.loads(http(port, "/exfil/clear", b'{}', fixture=fixture)).get("status") == "cleared", "receiver fixture cleanup failed")
        require(not any(entry.get("fixture_id") == fixture for entry in json.loads(http(port, "/exfil/log"))), "receiver fixture remains")
    elif family == "dvga":
        query = json.dumps({"query": "query getPastes { pastes(public: true, limit: 1) { id title } }"}).encode()
        require(json.loads(http(port, "/graphql", query)).get("data", {}).get("pastes"), "GraphQL database query failed")
    elif family == "restaurant":
        menu = json.loads(http(port, "/menu"))
        require(isinstance(menu, list) and menu and "name" in menu[0], "seeded menu unavailable")

def crapi_functional():
    require("<html" in http(18888, "/").lower(), "crAPI frontend missing")
    login = json.loads(http(18888, "/identity/api/auth/login",
                            b'{"email":"admin@example.com","password":"Admin!123"}'))
    token = login.get("token") or login.get("access_token")
    require(isinstance(token, str) and token, "crAPI login failed")
    # OWASP/crAPI 700f03d services/community/api/models/post.go: PostsResponse, not a top-level list.
    page = json.loads(http(18888, "/community/api/v2/community/posts/recent?limit=1&offset=0", token=token))
    require(isinstance(page, dict), "crAPI community response unavailable")
    posts = page.get("posts")
    require(isinstance(posts, list) and posts and all(
            isinstance(post, dict) and all(isinstance(post.get(key), str) and post[key].strip()
                                          for key in ("id", "title", "content"))
            for post in posts), "crAPI community data unavailable")
    require(type(page.get("total")) is int and page["total"] == len(posts) and
            all(key in page and (page[key] is None or type(page[key]) is int and page[key] >= 0)
                for key in ("next_offset", "previous_offset")), "crAPI community pagination invalid")
    chatbot = json.loads(http(18888, "/chatbot/genai/state", token=token))
    require(chatbot.get("initialized") in ("false", False), "chatbot uninitialized state unavailable")
    products = json.loads(http(18888, "/workshop/api/shop/products", token=token))
    require(products.get("products") and "credit" in products, "crAPI workshop data unavailable")
    require("items" in json.loads(http(18025, "/api/v2/messages")), "mail service unavailable")

def check():
    checks = []
    def record(name, fn):
        try:
            fn()
            checks.append({"name": name, "ready": True})
        except Exception as exc:
            # Only allowlisted phase/status/type: never HTTP bodies, tokens or command argv.
            checks.append({"name": name, "ready": False, **diagnostic(exc)})
    for service in ("docker", "nginx"):
        record("service:" + service, lambda s=service: command("systemctl", "is-active", "--quiet", s))
    for family, first in FAMILIES.items():
        for index in range(1, 5):
            name = family + "-" + str(index)
            def probe(f=family, p=first+index-1, n=name):
                container(n)
                replica(f, p)
            record(name, probe)
    for name in ["dvwa-db", "restaurant-db"] + CRAPI:
        record(name, lambda n=name: container(n, n != "dvwa-db"))
    record("dvwa-database", lambda: require(int(command("docker", "exec", "dvwa-db", "mariadb",
           "-udvwa", "-pp@ssw0rd", "dvwa", "-Nse", "SELECT COUNT(*) FROM users")) >= 1, "empty users"))
    record("restaurant-database", lambda: require(command("docker", "exec", "restaurant-db",
           "psql", "-U", "admin", "-d", "restaurant", "-Atc", "SELECT 1") == "1", "SQL failed"))
    record("crapi-database", lambda: require(command("docker", "exec", "crapi-postgres",
           "psql", "-U", "admin", "-d", "crapi", "-Atc", "SELECT 1") == "1", "SQL failed"))
    record("crapi-functional", crapi_functional)
    return {"schema_version": 1, "ready": all(c["ready"] for c in checks), "checks": checks}

def main():
    global DEADLINE
    parser = argparse.ArgumentParser()
    parser.add_argument("--timeout-seconds", type=int, default=60)
    parser.add_argument("--initialize", action="store_true")
    args = parser.parse_args()
    if args.timeout_seconds <= 0:
        parser.error("timeout must be positive")
    DEADLINE = time.monotonic() + args.timeout_seconds
    if args.initialize:
        try:
            initialize()
        except Exception as exc:
            print(json.dumps({"schema_version": 1, "ready": False, **diagnostic(exc)}))
            return 1
    while True:
        report = check()
        if report["ready"] or time.monotonic() >= DEADLINE:
            print(json.dumps(report, separators=(",", ":")))
            return 0 if report["ready"] else 1
        time.sleep(min(2, max(0, DEADLINE-time.monotonic())))

if __name__ == "__main__":
    raise SystemExit(main())

#!/bin/sh
PROGRESS_LOG="/var/log/cloud-init-progress.log"
log_phase() { _p="$1"; shift; printf '[%s] [%s] %s\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)" "$_p" "${*:-started}" | tee -a "$PROGRESS_LOG" >&2; }
retry_cmd() { _m="$1"; _b="$2"; shift 2; _a=1; while [ "$_a" -le "$_m" ]; do if "$@"; then return 0; fi; [ "$_a" -lt "$_m" ] && { _w=$((_b*_a)); log_phase retry "$_a/$_m failed ($1) retry in ${_w}s"; sleep "$_w"; }; _a=$((_a+1)); done; log_phase retry "FAILED after $_m: $1"; return 1; }
fetch_url() { log_phase fetch "${3:-$1}"; retry_cmd 4 5 curl -fsSL --connect-timeout 15 --max-time 300 -o "$2" "$1"; }
install_packages() { log_phase apt "installing: $*"; retry_cmd 3 10 timeout 900 apt-get install -y -o DPkg::Lock::Timeout=60 "$@"; }

